def syms(m):
 import numpy as np
 a=np.array(m); forms={'h':a[::-1,:], 'v':a[:,::-1], 'r180':a[::-1,::-1], 't':a.T}
 return [k for k,b in forms.items() if b.shape==a.shape and np.array_equal(a,b)]
